# Tcl script for OpenROAD to produce cell-usage summary

# Ensure output directory exists
file mkdir outputs

# Initialize an associative array to store cell counts
array set cell_counts {}
set total_count 0

# Get all instances in the design
# -hierarchical is needed to get instances within the top level
set instances [get_cells -hierarchical *]

foreach inst $instances {
    # Get the reference cell name (the type)
    set cell_type [get_property $inst ref_name]

    # Skip if cell_type is empty (should not happen for valid instances)
    if { $cell_type eq "" } {
        continue
    }

    # Check if the cell is a physical-only cell (tap, endcap, filler)
    # Patterns to exclude:
    # - Tap/Endcap: TAPCELL*, ENDCAP* (though ENDCAP might be part of TAPCELL or separate)
    # - Filler: FILLCELL*
    # Note: The platform doc mentions TAPCELL_X1 as tap/endcap. 
    # Filler cells are FILLCELL_X1 ... FILLCELL_X32.

    set is_excluded 0
    if { [string match -nocase "TAPCELL*" $cell_type] } {
        set is_excluded 1
    } elseif { [string match -nocase "ENDCAP*" $cell_type] } {
        set is_excluded 1
    } elseif { [string match -nocase "FILLCELL*" $cell_type] } {
        set is_excluded 1
    }

    # If not excluded, count it
    if { $is_excluded == 0 } {
        if { [info exists cell_counts($cell_type)] } {
            incr cell_counts($cell_type)
        } else {
            set cell_counts($cell_type) 1
        }
        incr total_count
    }
}

# Open the output file
set output_file "outputs/cell_usage.txt"
set fid [open $output_file w]

# Write each cell type and its count
# The order is not specified, so we can iterate the array. 
# However, array iteration order is not guaranteed. 
# The task says "any order".
foreach cell_type [array names cell_counts] {
    puts $fid "$cell_type $cell_counts($cell_type)"
}

# Write the total
puts $fid "total $total_count"

close $fid

# Ensure the output directory exists
if { ![file exists outputs] } {
    file mkdir outputs
}

# 1. Identify the clock root net
set clk_port [get_ports clk]
if { [llength $clk_port] == 0 } {
    puts "Error: clk port not found"
    exit 1
}

# Get the pin associated with the port
set clk_port_pins [get_pins -of_objects $clk_port]
if { [llength $clk_port_pins] == 0 } {
    puts "Error: clk port has no pin"
    exit 1
}
set clk_port_pin [lindex $clk_port_pins 0]

# Get the net driven by the port pin
set clk_net [get_net -of_objects $clk_port_pin]
if { [llength $clk_net] == 0 } {
    puts "Error: clk net not found"
    exit 1
}

# 2. Get all BUF_X4 instances
set all_bufs [get_cells -hierarchical -filter "ref_name == BUF_X4"]

# 3. BFS to assign levels and count sinks
set queue [list]
set visited [dict create]
set results [dict create]

# Find Level 1 buffers: those driven by clk_net
set l1_candidates [list]
foreach buf $all_bufs {
    set input_pin [get_pins -of_objects $buf -filter "direction == input"]
    if { [llength $input_pin] > 0 } {
        set net [get_net -of_objects [lindex $input_pin 0]]
        if { $net == $clk_net } {
            lappend l1_candidates $buf
        }
    }
}

# Initialize queue with Level 1
foreach buf $l1_candidates {
    set buf_name [get_name $buf]
    if { ![dict exists $visited $buf_name] } {
        dict set visited $buf_name 1
        lappend queue "$buf_name 1"
    }
}

# Process queue
while { [llength $queue] > 0 } {
    set current [lindex $queue 0]
    set queue [lrange $queue 1 end]

    set buf_name [lindex $current 0]
    set level [lindex $current 1]
    set next_level [expr {$level + 1}]

    # Get the buffer object to find its output net
    set buf_obj [get_cells $buf_name]
    set output_pin [get_pins -of_objects $buf_obj -filter "direction == output"]
    if { [llength $output_pin] == 0 } {
        continue
    }
    set out_net [get_net -of_objects [lindex $output_pin 0]]

    # Count register sinks driven by this net
    set connected_pins [get_pins -of_objects $out_net]
    set ff_count 0

    foreach pin $connected_pins {
        set dir [get_property $pin direction]
        if { $dir != "input" } {
            continue
        }
        if { ![get_property $pin is_clock] } {
            continue
        }
        set inst [get_property $pin hierarchical_ref]
        set cell_name [get_property $inst ref_name]

        # Exclude buffers, inverters, fillers, taps, tie-cells
        if { [string match "BUF_*" $cell_name] || \
             [string match "INV_*" $cell_name] || \
             [string match "CLKBUF_*" $cell_name] || \
             [string match "FILLCELL*" $cell_name] || \
             [string match "TAPCELL*" $cell_name] || \
             [string match "LOGIC0*" $cell_name] || \
             [string match "LOGIC1*" $cell_name] } {
            continue
        }

        incr ff_count
    }

    dict set results $buf_name "$level $ff_count"

    # Find next level buffers
    foreach buf $all_bufs {
        set input_pin [get_pins -of_objects $buf -filter "direction == input"]
        if { [llength $input_pin] > 0 } {
            set net [get_net -of_objects [lindex $input_pin 0]]
            if { $net == $out_net } {
                set buf_name_next [get_name $buf]
                if { ![dict exists $visited $buf_name_next] } {
                    dict set visited $buf_name_next $next_level
                    lappend queue "$buf_name_next $next_level"
                }
            }
        }
    }
}

# 4. Write output
set out_file "outputs/ct06_clock_tree.txt"
set fid [open $out_file w]

set sorted_bufs [lsort [dict keys $results]]

foreach buf_name $sorted_bufs {
    set data [dict get $results $buf_name]
    set level [lindex $data 0]
    set sinks [lindex $data 1]
    set cell_name [get_property [get_cells $buf_name] ref_name]
    puts $fid "$buf_name $cell_name $level $sinks"
}

close $fid

# Ensure the output directory exists
