# Helper procedure to compute HPWL for a single net
proc compute_net_hpwl { net } {
    set pins [get_pins -of_objects $net -filter "IS_OUT != 1 && IS_IN != 1"]
    # Also include output pins from drivers and input pins from loads
    # Actually, get_pins -of_objects $net should give all pins connected to the net

    if { [llength $pins] < 2 } {
        return 0
    }

    set min_x 1e9
    set max_x -1e9
    set min_y 1e9
    set max_y -1e9

    foreach pin $pins {
        # Get the location of the pin
        set loc [get_property $pin LOCATION]
        if { $loc == "" } {
            # Try to get center of pin shape
            set center [get_property $pin CENTER]
            if { $center != "" } {
                set x [lindex $center 0]
                set y [lindex $center 1]
            } else {
                continue
            }
        } else {
            # LOCATION is typically "X Y" string
            scan $loc "%f %f" x y
        }

        if { $x < $min_x } { set min_x $x }
        if { $x > $max_x } { set max_x $x }
        if { $y < $min_y } { set min_y $y }
        if { $y > $max_y } { set max_y $y }
    }

    if { $min_x == 1e9 } {
        return 0
    }

    set width [expr {$max_x - $min_x}]
    set height [expr {$max_y - $min_y}]
    return [expr {$width + $height}]
}

