    # Fillers are FILLCELL*.
    # Other cells like INV, BUF, AOI, OAI, XOR, etc. have logic functions.

    # Increment the count for this cell type
    if {[info exists cell_counts($master)]} {
        set cell_counts($master) [expr {$cell_counts($master) + 1}]
    } else {
        set cell_counts($master) 1
    }

    # Increment total count
