# 2. BFS to find all clock tree nets
set clock_nets [list $top_clk_net]
set visited_nets [dict create]
dict set visited_nets $top_clk_net 1

# Queue for BFS
set queue [list $top_clk_net]

while {[llength $queue] > 0} {
    set current_net [lindex $queue 0]
    set queue [lrange $queue 1 end]

    # Get all pins driven by this net
    set driven_pins [get_pins -of_objects $current_net -filter "direction==output"]

    foreach pin $driven_pins {
        # Get the cell driving this pin
        set cell [get_cells -of_objects $pin]
        if {[llength $cell] == 0} {
            continue
        }
        set cell [lindex $cell 0]

        # Get the cell type
        set cell_type [get_property LIB_PIN [get_pins -of_objects $cell]]
        # Actually, get_property CELL_NAME [get_cells $cell]
        set cell_name [get_property NAME $cell]

        # Check if this cell is a buffer or inverter (likely part of clock tree)
        # We assume that clock tree cells are BUF* or INV* or CLKBUF*
        if {[string match -nocase "BUF*" $cell_name] || [string match -nocase "INV*" $cell_name] || [string match -nocase "CLKBUF*" $cell_name]} {
            # Get output pins of this cell
            set out_pins [get_pins -of_objects $cell -filter "direction==output"]
            foreach out_pin $out_pins {
                set out_net [get_nets -of_objects $out_pin]
                if {[llength $out_net] > 0} {
                    set out_net [lindex $out_net 0]
                    if {![dict exists $visited_nets $out_net]} {
                        dict set visited_nets $out_net 1
                        lappend clock_nets $out_net
                        lappend queue $out_net
                    }
                }
            }
        }
    }
}

