# Get all top-level ports of the current design
set ports [get_ports]

foreach port $ports {
    set port_name [get_property $port NAME]
    set direction [get_property $port DIRECTION]

    # Check if it's a bus (multi-bit) by looking for '[' in the name
    if { [string match "*[*" $port_name] } {
        # It is a bus. Parse the name to get the bit range.
        # Example names: req_msg[31:0], resp_msg[15:0], etc.

        # Find the start and end of the bracketed part
        set start [string first "{" $port_name]
        if { $start == -1 } {
            set start [string first "[" $port_name]
        }
        set end [string last "}" $port_name]
        if { $end == -1 } {
            set end [string last "]" $port_name]
        }

        if { $start != -1 && $end != -1 } {
            set range_str [string range $port_name [expr {$start + 1}] [expr {$end - 1}]]

            # Split by ':' to get high and low
            set bits [split $range_str :]
            set high [lindex $bits 0]
            set low [lindex $bits 1]

            # If only one index (e.g. [0]), it might be a single bit but named with brackets? 
            # Or it could be a single bit bus. If low is empty, assume high=low.
            if { [string length $low] == 0 } {
                set low $high
            }

            # Ensure they are integers
            set high [expr {int($high)}]
            set low [expr {int($low)}]

            # Iterate from low to high
            for { set i $low } { $i <= $high } { incr i } {
                puts $fid "$port_name[$i] $direction"
            }
        } else {
            # Fallback if parsing fails, just write the port as is
            puts $fid "$port_name $direction"
        }
    } else {
        # Single bit port
        puts $fid "$port_name $direction"
    }
}

