# For flop_types.txt, we already have a working method using all_registers and get_cells.
# Let's reuse that.

# For flop_clock_drivers.txt, we need to find the driver of the clock pin.
# We can iterate over all FF instances, get their clock pin, get the net, and find the driver instance.

# Using the database:
# For each FF instance, get its master (cell) and check if it's a FF? No, we already have the list.

# Let's try to get the clock pin net from the database.
# For each FF instance:
#   inst = instance
#   Find the clock pin on the master. Usually named "CK" or "CLK".
#   Get the pin object on the instance.
#   Get the net connected to that pin.
#   Find the driver of that net.

set driver_counts [dict create]

foreach inst_name $ff_instances {
    # Get the instance object from the database
    # ord::get_db_inst_by_name might be available
    set inst [ord::get_db_inst_by_name $inst_name]
    if {$inst eq ""} {
        continue
    }

    # Get the master (cell) of the instance
    set master [$inst getMaster]
    set cell_name [$master getName]

    # Get the pins of the master
    set master_pins [$master getPins]

    # Find the clock pin. Usually named CK, CLK, or C.
    set clk_pin_obj ""
    foreach pin $master_pins {
        set pin_name [$pin getName]
        if {[string match -nocase "*CK*" $pin_name] || [string match -nocase "*CLK*" $pin_name] || [string match -nocase "*C*" $pin_name]} {
            # Check if it's an input
            if {[$pin getDirection] == "input"} {
                set clk_pin_obj $pin
                break
            }
        }
    }

    if {$clk_pin_obj eq ""} {
        continue
    }

    # Get the pin on the instance
    set inst_pin [$inst findPin [$clk_pin_obj getName]]
    if {$inst_pin eq ""} {
        continue
    }

    # Get the net connected to this pin
    set net [$inst_pin getNet]
    if {$net eq ""} {
        continue
    }

    # Find the driver of this net
    # The driver is the pin on another instance that drives this net.
    # We need to find all pins on this net that are outputs.
    set net_pins [$net getPins]
    set driver_inst ""
    foreach pin $net_pins {
        if {[$pin getDirection] == "output"} {
            set driver_inst [$pin getInst]
            break
        }
    }

    if {$driver_inst ne ""} {
        set driver_name [$driver_inst getName]
        if {[dict exists $driver_counts $driver_name]} {
            dict set driver_counts $driver_name [expr {[dict get $driver_counts $driver_name] + 1}]
        } else {
            dict set driver_counts $driver_name 1
        }
    }
}

