foreach inst_name [dict keys $pre_positions] {
    if {[dict exists $post_positions $inst_name]} {
        set pre [dict get $pre_positions $inst_name]
        set post [dict get $post_positions $inst_name]

        set dx [expr {[lindex $post 0] - [lindex $pre 0]}]
        set dy [expr {[lindex $post 1] - [lindex $pre 1]}]

        set adx [expr {abs($dx)}]
        set ady [expr {abs($dy)}]

        set disp [expr {$adx + $ady}]

        lappend displacements [list $inst_name $disp]
    }
}

# Sort the list by displacement in descending order
set sorted_displacements [lsort -real -decreasing -index 1 $displacements]

# 5. Write the top 5 to outputs/top_displaced.txt
set fp [open outputs/top_displaced.txt w]
set count 0
foreach item $sorted_displacements {
    if {$count >= 5} {
        break
    }
    set inst_name [lindex $item 0]
    set disp [lindex $item 1]
    puts $fp "$inst_name [format %.3f $disp]"
    incr count
}
close $fp

proc calculate_hpwl { } {
    set total_hpwl 0
    set nets [get_nets -filter {is_power == false && is_ground == false}]

    foreach net $nets {
        set pins [get_pins -of_objects $net]
        if {[llength $pins] < 2} {
            continue
        }

        set min_x 1e9
        set min_y 1e9
        set max_x -1e9
        set max_y -1e9

        foreach pin $pins {
            set loc [get_property $pin location]
            if {$loc != ""} {
                set x [lindex $loc 0]
                set y [lindex $loc 1]
                if {$x < $min_x} { set min_x $x }
                if {$x > $max_x} { set max_x $x }
                if {$y < $min_y} { set min_y $y }
                if {$y > $max_y} { set max_y $y }
            }
        }

        if {$min_x != 1e9 && $max_x != -1e9} {
            set hpwl [expr {($max_x - $min_x) + ($max_y - $min_y)}]
            set total_hpwl [expr {$total_hpwl + $hpwl}]
        }
    }

    return $total_hpwl
}

