# Procedure to calculate HPWL
proc calculate_hpwl { } {
    set total_hpwl 0
    set nets [get_nets]

    foreach net $nets {
        set name [get_property $net name]
        # Exclude power and ground nets (common names: VDD, VSS, VDD!, VSS!, etc.)
        if {$name eq "VDD" || $name eq "VSS" || $name eq "VDD!" || $name eq "VSS!" || 
            [string match "*VDD*" $name] || [string match "*VSS*" $name]} {
            continue
        }

        set pins [get_pins -of_objects $net]
        if {[llength $pins] < 2} {
            continue
        }

        set min_x 1e9
        set min_y 1e9
        set max_x -1e9
        set max_y -1e9

        foreach pin $pins {
            set loc [get_property $pin location]
            if {$loc != ""} {
                set x [lindex $loc 0]
                set y [lindex $loc 1]
                if {$x < $min_x} { set min_x $x }
                if {$x > $max_x} { set max_x $x }
                if {$y < $min_y} { set min_y $y }
                if {$y > $max_y} { set max_y $y }
            }
        }

        if {$min_x != 1e9 && $max_x != -1e9} {
            set hpwl [expr {($max_x - $min_x) + ($max_y - $min_y)}]
            set total_hpwl [expr {$total_hpwl + $hpwl}]
        }
    }

    return $total_hpwl
}

# Get HPWL before optimization
set hpwl_before [calculate_hpwl]

# Run detailed placement optimization
optimize_mirroring
