# 2. Get the net connected to the clock port
# The port is connected to a net. This net is the root of the clock tree.
set clk_net_list [get_nets -of_objects $clk_port]
if {[llength $clk_net_list] != 1} {
    puts "Error: Clock port 'clk' is not connected to exactly one net."
    exit 1
}
set clk_net [lindex $clk_net_list 0]

# 3. Identify all clock tree nets
# We start with the clk_net and find all nets connected to clock pins (clk, clk_n) of instances.
set clock_nets [list $clk_net]
set processed_nets [dict create $clk_net 1]

# Iterate through all instances to find clock pins and their nets
foreach inst [get_instances] {
    # Get pins of this instance
    foreach pin [get_pins -of_objects $inst] {
        # Check if the pin name is a clock pin (case insensitive)
        set pin_name [string tolower [get_name -quiet $pin]]
        # Common clock pin names: clk, clk_n, clock, clock_n, CLK, CLK_N, etc.
        if {[regexp {^clk$|^clk_n$|^clock$|^clock_n$} $pin_name]} {
            # Get the net connected to this pin
            set net [get_nets -of_objects $pin]
            if {$net ne ""} {
                if {![dict exists $processed_nets $net]} {
                    dict set processed_nets $net 1
                    lappend clock_nets $net
                }
            }
        }
    }
}

